-- যাচাই: প্রকাশিত মণ্ডপ ও স্থানাঙ্কসহ মণ্ডপের সংখ্যা (১১৩ ও ১১৩ আসার কথা)
select y.year, y.status,
       count(m.id) filter (where m.status = 'published') as প্রকাশিত,
       count(m.id) filter (where m.latitude is not null) as স্থানাঙ্কসহ
from public.puja_years y
left join public.mandapas m on m.year_id = y.id
group by y.id, y.year, y.status
order by y.year desc;

-- এলাকা ধরে গণনা (মহানগর ৮১, উত্তর ৭, দক্ষিণ ২৫ আসার কথা)
select area, count(*) as সংখ্যা
from public.mandapas m join public.puja_years y on y.id = m.year_id
where y.year = 2026 and m.status = 'published'
group by area order by area;
